using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Implementations ---

/// <summary>
/// Simulates web search by fetching real search-result snippets from Wikipedia's API.
/// </summary>
public sealed class WebSearchTool
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information on a given query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍  Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=5&format=json";
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var results = doc.RootElement
                .GetProperty("query")
                .GetProperty("search")
                .EnumerateArray()
                .Select(r => $"• {r.GetProperty("title").GetString()}: "
                           + $"{StripHtml(r.GetProperty("snippet").GetString() ?? "")}")
                .ToList();

            return results.Count > 0
                ? string.Join("\n", results)
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string StripHtml(string html)
        => System.Text.RegularExpressions.Regex.Replace(html, "<.*?>", "");
}

/// <summary>
/// Lets the agent save, list, and clear structured research notes.
/// </summary>
public sealed class NoteTakingTool
{
    private static readonly List<(string Topic, string Content)> Notes = [];

    [Description("Save a research note under a topic heading.")]
    public static string SaveNote(
        [Description("Short topic label for the note")] string topic,
        [Description("The note content to save")] string content)
    {
        Notes.Add((topic, content));

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝  Note saved under \"{topic}\"");
        Console.ResetColor();

        return $"Note saved ({Notes.Count} total).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (Notes.Count == 0) return "No notes saved yet.";

        return string.Join("\n\n", Notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Topic} ---\n{n.Content}"));
    }

    [Description("Clear all saved notes.")]
    public static string ClearNotes()
    {
        var count = Notes.Count;
        Notes.Clear();
        return $"Cleared {count} note(s).";
    }
}

// --- Main program ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.ResetColor();
    return 1;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(NoteTakingTool.SaveNote),
    AIFunctionFactory.Create(NoteTakingTool.GetNotes),
    AIFunctionFactory.Create(NoteTakingTool.ClearNotes),
};

var systemPrompt = """
    You are a research agent. Your goal is to thoroughly research the topic
    the user provides and produce a well-structured summary.

    Workflow:
    1. Break the topic into 2-3 key subtopics.
    2. Use the SearchWeb tool to find information on each subtopic.
    3. Use SaveNote to record important findings as you go.
    4. After researching, use GetNotes to review everything you collected.
    5. Produce a final, well-organized summary with sections and key takeaways.

    Be thorough but concise. Cite the sources you found when possible.
    """;

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🤖 AI Research Agent           ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.White;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new ChatOptions { Tools = [.. tools] };

    try
    {
        var response = await client.GetResponseAsync(messages, options);

        Console.ForegroundColor = ConsoleColor.Cyan;
        Console.WriteLine("\n════════════ Research Summary ════════════\n");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.ForegroundColor = ConsoleColor.Cyan;
        Console.WriteLine("\n══════════════════════════════════════════\n");
        Console.ResetColor();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");
return 0;

