         Notes.Add((topic, content));

         Console.ForegroundColor = ConsoleColor.DarkYellow;
         Console.WriteLine($"  📝  Note saved under \"{topic}\"");
         Console.ResetColor();

         return $"Note saved ({Notes.Count} total).";
     }

     [Description("Retrieve all saved research notes.")]
     public static string GetNotes()
     {
         if (Notes.Count == 0) return "No notes saved yet.";

         return string.Join("\n\n", Notes.Select((n, i) =>
             $"--- Note {i + 1}: {n.Topic} ---\n{n.Content}"));
     }

     [Description("Clear all saved notes.")]
