/// </summary>
public sealed class WebSearchTool
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information on a given query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍  Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=5&format=json";
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var results = doc.RootElement
                .GetProperty("query")
                .GetProperty("search")
                .EnumerateArray()
                .Select(r => $"• {r.GetProperty("title").GetString()}: "
                           + $"{StripHtml(r.GetProperty("snippet").GetString() ?? "")}")
                .ToList();

            return results.Count > 0
                ? string.Join("\n", results)
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string StripHtml(string html)
        => Regex.Replace(html, "<.*?>", "");
}
"}

